/* @lc app=leetcode id=2713 lang=kotlin */ class Solution { fun maxIncreasingCells(grid: Array<IntArray>): Int = grid.flatMapIndexed { r, row -> row.mapIndexed { c, v -> Triple(v, r, c) } }.groupBy { it.first }.toSortedMap().values.fold(IntArray(grid.size) to IntArray(grid[0].size)) { (rM, cM), cells -> cells.map { (_, r, c) -> maxOf(rM[r], cM[c]) + 1 }.let { dp -> dp.forEachIndexed { i, d -> cells[i].let { (_, r, c) -> rM.also { it[r] = maxOf(it[r], d) }.also { cM[c] = maxOf(cM[c], d) } } }.run { rM to cM } } }.let { (r, c) -> maxOf(r.maxOrNull() ?: 0, c.maxOrNull() ?: 0) } }